typedef unsigned int uint32; typedef float rational_t;
struct QWdata {}; struct sceDmaChcr { unsigned int DIR:1; unsigned int:1; unsigned int MOD:2; unsigned int ASP:2; unsigned int TTE:1; unsigned int TIE:1; unsigned int STR:1; }; struct sceDmaChan { sceDmaChcr chcr; };
int nglGetScreenWidth(); int nglGetScreenHeight(); void nglSetPerspectiveMatrix(float,float,float,float,float,float,float,float,int,int); sceDmaChan *sceDmaGetChan(int); int sceGsSyncV(int);
extern float field_of_view_fudge; extern float PROJ_ZOOM; extern unsigned char PortScratchPad[1024];
__asm__(".equ nglGetScreenWidth__Fv, 0x00395D88"); __asm__(".equ nglGetScreenHeight__Fv, 0x00395D98"); __asm__(".equ nglSetPerspectiveMatrix__Ffffffffii, 0x00398C40"); __asm__(".equ sceDmaGetChan, 0x003BAF88"); __asm__(".equ sceGsSyncV, 0x003BA3D0"); __asm__(".equ field_of_view_fudge, 0x00424F38"); __asm__(".equ PROJ_ZOOM, 0x0043286C"); __asm__(".equ PortScratchPad, 0x0041E740");
const rational_t PROJ_FIELD_OF_VIEW=1.570795f; const rational_t PI=3.14159265358979323846f; inline rational_t proj_field_of_view_in_degrees(void){return(PROJ_FIELD_OF_VIEW*field_of_view_fudge*PROJ_ZOOM*180.0f/PI);}
#define PROJECT_KELLYSLATER
#define SCE_DMA_GIF 2
#define SCE_DMA_VIF1 1
#define SCRATCHPAD (uint32)(&PortScratchPad)
class hw_rasta { char fields_before_screen_width[0x270]; int screen_width,screen_height; int pixel_depth; sceDmaChan*dmaGif; sceDmaChan*dmaVif; QWdata*dma_data; public:void init_ps2_gfx(); };
void hw_rasta::init_ps2_gfx()
{
#ifdef DEBUG
static bool ps2_gfx_are_initialized = false;
assert (ps2_gfx_are_initialized == false);
ps2_gfx_are_initialized = true;
#endif

  screen_width = nglGetScreenWidth(); //HWOSPS2_DEFAULT_SCREEN_WIDTH;
  screen_height = nglGetScreenHeight(); //HWOSPS2_DEFAULT_SCREEN_HEIGHT;
  pixel_depth = 32;

#ifdef PROJECT_KELLYSLATER
  nglSetPerspectiveMatrix( proj_field_of_view_in_degrees(), nglGetScreenWidth()/2, nglGetScreenHeight()/2, 0.2f, 65536.0f );
#else
  nglSetPerspectiveMatrix( 90.0f, nglGetScreenWidth()/2, nglGetScreenHeight()/2, PROJ_NEAR_PLANE_D, PROJ_FAR_PLANE_D );
#endif

  // get the GIF dma channel  (GIF is the GS interface)
  dmaGif = sceDmaGetChan(SCE_DMA_GIF);
  // enable Tag Transer
  dmaGif->chcr.TTE = 1;
	// get the VIF1 dma channel (VU1 interface)
	dmaVif = sceDmaGetChan(SCE_DMA_VIF1);
  dmaVif->chcr.TTE = 1;

  // use scratchpad for packet
  dma_data = (QWdata*)SCRATCHPAD;

//  low_level_console_init();

	// wait for odd field
  while(sceGsSyncV(0) == 0);
}
